"""Build PR packages for build inputs; main still packages every source change."""
from fnmatch import fnmatchcase
import os
import subprocess
from pathlib import Path

PACKAGE_RESOURCES = (
    'app/icons/',
    'runtime/umeko-docs/',
    # Generated by setup, but fail open if a PR explicitly changes them.
    'runtime/node/',
    'runtime/releases/',
)
PACKAGE_FILES = {
    'app/theme-prompt.txt',
    'app/character-defaults.json',
    'app/provider-presets.json',
    'runtime/umeko-operations.json',
    'runtime/webview-component.json',
}


def needs_packages(paths):
    return any(is_package_input(path) for path in paths)


def is_package_input(path):
    if (path in PACKAGE_FILES or path.startswith(PACKAGE_RESOURCES)
            or fnmatchcase(path, 'runtime/package*.json')
            or Path(path).match('requirements*.txt')
            or path.endswith('.spec')):
        return True
    # Ordinary source changes get shared + Windows-native PR checks. The full
    # main matrix catches their packaging regressions before release.
    if path.startswith(('app/', 'runtime/', 'tests/', 'docs/', 'docs-site/')):
        return False
    if path in ('scripts/capture-documentation.py', '.github/workflows/docs.yml'):
        return False
    # Unclassified paths fail open: build/setup scripts, dependency pins,
    # packaging workflows/configuration and explicitly copied resources.
    return True


if __name__ == '__main__':
    result = subprocess.run(
        ['git', 'diff', '--name-only', '-z', os.environ['PR_BASE'], 'HEAD'],
        check=True, capture_output=True,
        creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
    paths = result.stdout.decode('utf-8', errors='surrogateescape').split('\0')
    paths = [p for p in paths if p]
    packages = needs_packages(paths)
    with Path(os.environ['GITHUB_OUTPUT']).open('a', encoding='utf-8') as output:
        output.write(f'packages={str(packages).lower()}\n')
    print(f'Native packages required: {packages}')
